/** The same bounds are enforced before upload and by the private upload verifier. */
export const ORIGINAL_AUDIO_MAX_BYTES = 50 * 1024 * 1024;
export const ORIGINAL_AUDIO_MAX_SECONDS = 600;
export const ORIGINAL_AUDIO_ACCEPT = '.wav,.mp3,.m4a,audio/wav,audio/mpeg,audio/mp4';
export type OriginalAudioInfo = { mime: 'audio/wav' | 'audio/mpeg' | 'audio/mp4'; extension: 'wav' | 'mp3' | 'm4a'; durationSec: number };

function fail(): never { throw new Error('Choose a complete WAV, MP3 or M4A audio file between 1 second and 10 minutes, under 50 MB.'); }
/** Container inspection does not execute a decoder. All lengths and loop counts are bounded. */
export function inspectOriginalAudio(bytes: Uint8Array): OriginalAudioInfo {
  if (bytes.length < 44 || bytes.length > ORIGINAL_AUDIO_MAX_BYTES) return fail();
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const text = (offset: number, length: number) => String.fromCharCode(...bytes.subarray(offset, offset + length));
  const finish = (durationSec: number, mime: OriginalAudioInfo['mime'], extension: OriginalAudioInfo['extension']) => {
    if (!Number.isFinite(durationSec) || durationSec < 1 || durationSec > ORIGINAL_AUDIO_MAX_SECONDS) return fail();
    return { durationSec, mime, extension };
  };
  if (text(0, 4) === 'RIFF' && text(8, 4) === 'WAVE') {
    if (view.getUint32(4, true) + 8 !== bytes.length) return fail();
    let rate = 0, block = 0, dataBytes = 0, format = false;
    for (let offset = 12, chunks = 0; offset + 8 <= bytes.length && chunks++ < 10000;) {
      const name = text(offset, 4), size = view.getUint32(offset + 4, true), start = offset + 8;
      if (size > bytes.length - start) return fail();
      if (name === 'fmt ') {
        if (size < 16 || format) return fail();
        const codec = view.getUint16(start, true), channels = view.getUint16(start + 2, true);
        const samples = view.getUint32(start + 4, true), bits = view.getUint16(start + 14, true);
        rate = view.getUint32(start + 8, true); block = view.getUint16(start + 12, true);
        if (![1, 3].includes(codec) || channels < 1 || channels > 8 || samples < 8000 || samples > 192000
          || ![8, 16, 24, 32, 64].includes(bits) || block !== channels * bits / 8 || rate !== samples * block) return fail();
        format = true;
      } else if (name === 'data') dataBytes += size;
      offset = start + size + (size % 2);
    }
    if (!format || !dataBytes || dataBytes % block) return fail();
    return finish(dataBytes / rate, 'audio/wav', 'wav');
  }
  if (text(4, 4) === 'ftyp') {
    type Box = { name: string; start: number; end: number };
    let boxCount = 0;
    const boxes = (start: number, end: number): Box[] => {
      const result: Box[] = [];
      for (let offset = start; offset < end;) {
        if (offset + 8 > end || ++boxCount > 100000) return fail();
        let size = view.getUint32(offset), header = 8;
        if (size === 1) {
          if (offset + 16 > end) return fail();
          const large = view.getBigUint64(offset + 8); if (large > BigInt(ORIGINAL_AUDIO_MAX_BYTES)) return fail();
          size = Number(large); header = 16;
        } else if (size === 0) size = end - offset;
        if (size < header || offset + size > end) return fail();
        result.push({ name: text(offset + 4, 4), start: offset + header, end: offset + size }); offset += size;
      }
      return result;
    };
    const child = (box: Box, name: string) => boxes(box.start, box.end).find(item => item.name === name);
    const top = boxes(0, bytes.length), moov = top.find(box => box.name === 'moov');
    if (!moov || !top.some(box => box.name === 'mdat' && box.end > box.start)) return fail();
    let duration = 0, tracks = 0;
    for (const trak of boxes(moov.start, moov.end).filter(box => box.name === 'trak')) {
      const mdia = child(trak, 'mdia'); if (!mdia) return fail();
      const hdlr = child(mdia, 'hdlr'), mdhd = child(mdia, 'mdhd'), minf = child(mdia, 'minf');
      if (!hdlr || hdlr.end - hdlr.start < 12 || text(hdlr.start + 8, 4) !== 'soun' || !mdhd || !minf) return fail();
      const version = bytes[mdhd.start], timescaleOffset = mdhd.start + (version === 1 ? 20 : 12);
      if (![0, 1].includes(version) || timescaleOffset + 4 > mdhd.end) return fail();
      const timescale = view.getUint32(timescaleOffset); if (!timescale) return fail();
      const stbl = child(minf, 'stbl'), dinf = child(minf, 'dinf');
      const stts = stbl && child(stbl, 'stts'), dref = dinf && child(dinf, 'dref');
      if (!stts || stts.start + 8 > stts.end || !dref || dref.start + 8 > dref.end) return fail();
      // External data references could otherwise describe media outside these bytes.
      const refs = boxes(dref.start + 8, dref.end);
      if (!refs.length || refs.some(ref => ref.name !== 'url ' || ref.end - ref.start !== 4 || (view.getUint32(ref.start) & 1) !== 1)) return fail();
      const entries = view.getUint32(stts.start + 4); if (entries > 100000 || stts.start + 8 + entries * 8 !== stts.end) return fail();
      let ticks = 0;
      for (let i = 0; i < entries; i++) {
        const p = stts.start + 8 + i * 8; ticks += view.getUint32(p) * view.getUint32(p + 4);
        if (!Number.isSafeInteger(ticks) || ticks / timescale > ORIGINAL_AUDIO_MAX_SECONDS) return fail();
      }
      duration = Math.max(duration, ticks / timescale); tracks++;
    }
    if (tracks !== 1) return fail();
    return finish(duration, 'audio/mp4', 'm4a');
  }
  let offset = 0;
  if (text(0, 3) === 'ID3') {
    if ([bytes[6], bytes[7], bytes[8], bytes[9]].some(value => value > 127)) return fail();
    offset = 10 + (bytes[6] << 21 | bytes[7] << 14 | bytes[8] << 7 | bytes[9]);
    if (bytes[5] & 16) offset += 10;
  }
  let duration = 0, frames = 0;
  while (offset + 4 <= bytes.length) {
    if (bytes.length - offset === 128 && text(offset, 3) === 'TAG') { offset = bytes.length; break; }
    const header = view.getUint32(offset), version = (header >>> 19) & 3, layer = (header >>> 17) & 3;
    const rateIndex = (header >>> 10) & 3, bitrateIndex = (header >>> 12) & 15, padding = (header >>> 9) & 1;
    if ((header >>> 21) !== 0x7ff || version === 1 || layer !== 1 || rateIndex === 3 || !bitrateIndex || bitrateIndex === 15) return fail();
    const rate = [44100, 48000, 32000][rateIndex] / (version === 3 ? 1 : version === 2 ? 2 : 4);
    const bitrate = (version === 3 ? [0,32,40,48,56,64,80,96,112,128,160,192,224,256,320] : [0,8,16,24,32,40,48,56,64,80,96,112,128,144,160])[bitrateIndex] * 1000;
    const size = Math.floor((version === 3 ? 144 : 72) * bitrate / rate) + padding;
    if (size < 4 || offset + size > bytes.length) return fail();
    offset += size; duration += (version === 3 ? 1152 : 576) / rate; frames++;
    if (duration > ORIGINAL_AUDIO_MAX_SECONDS || frames > 100000) return fail();
  }
  if (!frames || offset !== bytes.length) return fail();
  return finish(duration, 'audio/mpeg', 'mp3');
}

import { inspectOriginalAudio, ORIGINAL_AUDIO_MAX_BYTES } from '../../../shared/originalAudio.ts';
type Asset = { trackId:string;providerId:string;path:string;mime:string;bytes:number;sha256:string;status:'reserved'|'ready';soundId:string|null };
type Dependencies = {
 reserve(token:string,track:string,bytes:number,mime:string,sha256:string,signal:AbortSignal):Promise<Asset|null>;
 store(asset:Asset,bytes:Uint8Array,signal:AbortSignal):Promise<boolean>;
 read(token:string,asset:Asset,signal:AbortSignal):Promise<{response:Response;version:string}|null>;
 finish(token:string,asset:Asset,duration:number,sha256:string,version:string,signal:AbortSignal):Promise<string|null>;
 digest(bytes:Uint8Array):Promise<string>;
};
const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const reply=(status:number,value:unknown)=>new Response(JSON.stringify(value),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store'}});
function bounded<T>(promise:Promise<T>,signal:AbortSignal):Promise<T>{
 return new Promise((resolve,reject)=>{const abort=()=>reject(new Error('Deadline'));if(signal.aborted){abort();return;}signal.addEventListener('abort',abort,{once:true});promise.then(resolve,reject).finally(()=>signal.removeEventListener('abort',abort));});
}
async function bytesFrom(body:ReadableStream<Uint8Array>|null,expected:number,signal:AbortSignal):Promise<Uint8Array>{
 if(!body)throw new Error('Body required');
 const reader=body.getReader(),chunks:Uint8Array[]=[];let total=0;
 try{
  while(true){const next=await bounded(reader.read(),signal);if(next.done)break;total+=next.value.byteLength;if(total>expected||total>ORIGINAL_AUDIO_MAX_BYTES)throw new Error('Size exceeded');chunks.push(next.value);}
  if(total!==expected)throw new Error('Size mismatch');
  const output=new Uint8Array(total);let at=0;for(const chunk of chunks){output.set(chunk,at);at+=chunk.byteLength;}return output;
 }finally{void reader.cancel().catch(()=>{});reader.releaseLock();}
}
export function createCatalogueIngestHandler(deps:Dependencies){
 return async(request:Request):Promise<Response>=>{
  if(request.method!=='POST')return reply(405,{error:'Use POST'});
  const token=(request.headers.get('Authorization')||'').replace(/^Bearer /,''),track=request.headers.get('X-Catalogue-Track')||'',sha=request.headers.get('X-Audio-Sha256')||'';
  const count=request.headers.get('Content-Length')||'',size=Number(count),mime=request.headers.get('Content-Type')?.split(';')[0].trim().toLowerCase()||'';
  if(!/^pc_catalogue_[0-9a-f]{64}$/.test(token))return reply(401,{error:'Provider authentication required'});
  if(!UUID.test(track)||!/^\d+$/.test(count)||!Number.isSafeInteger(size)||size<44||size>ORIGINAL_AUDIO_MAX_BYTES||!['audio/wav','audio/mpeg','audio/mp4'].includes(mime)||!/^[a-f0-9]{64}$/.test(sha))return reply(400,{error:'Valid track, digest, content type and bounded byte length required'});
  const controller=new AbortController(),abort=()=>controller.abort(),timer=setTimeout(abort,45000);
  request.signal.addEventListener('abort',abort,{once:true});if(request.signal.aborted)abort();
  const signal=controller.signal;
  try{
   const asset=await bounded(deps.reserve(token,track,size,mime,sha,signal),signal);
   const ext=mime==='audio/wav'?'wav':mime==='audio/mpeg'?'mp3':'m4a';
   if(!asset||asset.trackId!==track||!/^[a-z0-9_-]{1,60}$/.test(asset.providerId)||asset.path!==`catalogue/${asset.providerId}/${track}/${sha}.${ext}`||asset.bytes!==size||asset.mime!==mime||asset.sha256!==sha)return reply(403,{error:'Catalogue ingestion is unavailable or its verified licence is missing'});
   if(asset.status==='ready'&&UUID.test(asset.soundId||'')){void request.body?.cancel().catch(()=>{});return reply(200,{soundId:asset.soundId,replayed:true});}
   if(asset.status!=='reserved')return reply(409,{error:'Catalogue asset unavailable'});
   const incoming=await bytesFrom(request.body,size,signal),inspected=inspectOriginalAudio(incoming);
   if(inspected.mime!==mime||await bounded(deps.digest(incoming),signal)!==sha)return reply(422,{error:'Audio verification failed'});
   if(!await bounded(deps.store(asset,incoming,signal),signal))return reply(503,{error:'Private storage is unavailable. Retry the same track revision.'});
   // Read the actual persisted object. A retry cannot adopt arbitrary existing
   // bytes just because Storage answered conflict for its immutable path.
   const stored=await bounded(deps.read(token,asset,signal),signal);
   if(!stored||!stored.response.ok||!stored.version){void stored?.response.body?.cancel().catch(()=>{});return reply(409,{error:'Stored asset is not ready for verification'});}
   const actual=await bytesFrom(stored.response.body,size,signal),verified=inspectOriginalAudio(actual),digest=await bounded(deps.digest(actual),signal);
   if(verified.mime!==mime||digest!==sha)return reply(409,{error:'Stored audio does not match this catalogue revision'});
   const soundId=await bounded(deps.finish(token,asset,verified.durationSec,digest,stored.version,signal),signal);
   if(!soundId||!UUID.test(soundId))return reply(409,{error:'The licence or stored audio changed before verification completed'});
   return reply(200,{soundId,replayed:false});
  }catch{return reply(controller.signal.aborted?408:422,{error:controller.signal.aborted?'Verification timed out. Retry this track revision.':'The catalogue audio could not be verified.'});}
  finally{clearTimeout(timer);request.signal.removeEventListener('abort',abort);controller.abort();}
 };
}

import { createClient } from 'npm:@supabase/supabase-js@2.112.3';
import { createCatalogueIngestHandler } from './handler.ts';
const base=Deno.env.get('SUPABASE_URL')!,key=Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
const client=createClient(base,key,{auth:{persistSession:false,autoRefreshToken:false}});
const objectUrl=(path:string)=>`${base}/storage/v1/object/music-audio/${path.split('/').map(encodeURIComponent).join('/')}`;
Deno.serve(createCatalogueIngestHandler({
 async reserve(token,track,bytes,mime,sha256,signal){const{data,error}=await client.rpc('reserve_catalogue_audio',{p_token:token,p_track:track,p_bytes:bytes,p_mime:mime,p_sha256:sha256,p_origin:base}).abortSignal(signal);return error?null:data;},
 async store(asset,bytes,signal){
  const response=await fetch(objectUrl(asset.path),{method:'POST',headers:{Authorization:`Bearer ${key}`,apikey:key,'Content-Type':asset.mime,'x-upsert':'false','Cache-Control':'no-store'},body:bytes,signal,redirect:'error'});
  void response.body?.cancel().catch(()=>{});return response.ok||response.status===409;
 },
 async read(token,asset,signal){
  const{data,error}=await client.rpc('catalogue_audio_object',{p_token:token,p_track:asset.trackId}).abortSignal(signal);
  if(error||!data?.version||Number(data.bytes)!==asset.bytes)return null;
  const response=await fetch(objectUrl(asset.path).replace('/object/','/object/authenticated/'),{headers:{Authorization:`Bearer ${key}`,apikey:key,'Cache-Control':'no-store'},cache:'no-store',signal,redirect:'error'});
  return{response,version:String(data.version)};
 },
 async finish(token,asset,duration,sha256,version,signal){const{data,error}=await client.rpc('finish_catalogue_audio',{p_token:token,p_track:asset.trackId,p_duration:duration,p_sha256:sha256,p_object_version:version}).abortSignal(signal);return error?null:data;},
 async digest(bytes){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(byte=>byte.toString(16).padStart(2,'0')).join('');},
}));
